package com.ella.simpleafktimer;

import java.awt.Color;
import java.awt.image.BufferedImage;
import java.time.Duration;
import java.time.Instant;
import java.time.temporal.ChronoUnit;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.infobox.Timer;

/**
 * A {@link Timer} that, instead of the base class's default behaviour of culling (removing) itself
 * once it counts down past zero, switches to showing "AFK" in red and stays visible - the plugin
 * removes it itself once the player is no longer idle.
 */
class AfkCountdownInfoBox extends Timer
{
	AfkCountdownInfoBox(long period, ChronoUnit unit, BufferedImage image, Plugin plugin)
	{
		super(period, unit, image, plugin);
	}

	private boolean isExpired()
	{
		Duration timeLeft = Duration.between(Instant.now(), getEndTime());
		return timeLeft.isZero() || timeLeft.isNegative();
	}

	@Override
	public String getText()
	{
		return isExpired() ? "AFK" : super.getText();
	}

	@Override
	public Color getTextColor()
	{
		return isExpired() ? Color.RED.brighter() : super.getTextColor();
	}

	@Override
	public boolean render()
	{
		return true;
	}

	@Override
	public boolean cull()
	{
		return false;
	}
}

package com.ella.simpleafktimer;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Notification;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(SimpleAfkTimerConfig.GROUP)
public interface SimpleAfkTimerConfig extends Config
{
	String GROUP = "simpleafktimer";

	@ConfigItem(
		keyName = "idleThreshold",
		name = "AFK threshold",
		description = "How long the game has to go without input (of the types enabled below) before you're "
			+ "considered AFK.",
		position = 0
	)
	@Range(min = 5, max = 3600)
	@Units(Units.SECONDS)
	default int idleThreshold()
	{
		return 300;
	}

	@ConfigSection(
		name = "Detection",
		description = "Which input types count toward the AFK threshold.",
		position = 1
	)
	String detectionSection = "detectionSection";

	@ConfigItem(
		keyName = "detectKeyboard",
		name = "Detect keyboard",
		description = "Count keyboard input toward the AFK threshold. Disable if mouse movement alone should be "
			+ "enough to keep you from going AFK.",
		position = 2,
		section = detectionSection
	)
	default boolean detectKeyboard()
	{
		return true;
	}

	@ConfigItem(
		keyName = "detectMouse",
		name = "Detect mouse",
		description = "Count mouse input toward the AFK threshold. Disable if keyboard input alone should be "
			+ "enough to keep you from going AFK.",
		position = 3,
		section = detectionSection
	)
	default boolean detectMouse()
	{
		return true;
	}

	@ConfigItem(
		keyName = "detectArrowKeys",
		name = "Detect arrow keys",
		description = "Arrow keys only move the camera, so the game's own keyboard-idle counter ignores them - "
			+ "this plugin tracks them separately and, when enabled, treats an arrow key press as activity that "
			+ "resets the AFK timer. Only applies while keyboard detection above is enabled.",
		position = 4,
		section = detectionSection
	)
	default boolean detectArrowKeys()
	{
		return true;
	}

	@ConfigSection(
		name = "Infobox",
		description = "The countdown infobox shown while you're idle.",
		position = 5
	)
	String infoboxSection = "infoboxSection";

	@ConfigItem(
		keyName = "showInfobox",
		name = "Show countdown infobox",
		description = "Show a sidebar infobox that counts down to the AFK threshold while you're idle.",
		position = 6,
		section = infoboxSection
	)
	default boolean showInfobox()
	{
		return true;
	}

	@ConfigItem(
		keyName = "infoboxDelay",
		name = "Infobox delay",
		description = "How long to stay idle before the countdown infobox appears. 0 shows it as soon as you go "
			+ "idle.",
		position = 7,
		section = infoboxSection
	)
	@Range(min = 0, max = 3600)
	@Units(Units.SECONDS)
	default int infoboxDelay()
	{
		return 5;
	}

	@ConfigSection(
		name = "Repeat",
		description = "Whether and how often to repeat the notification while you stay AFK.",
		position = 8
	)
	String repeatSection = "repeatSection";

	@ConfigItem(
		keyName = "repeatNotification",
		name = "Repeat while AFK",
		description = "If checked, keep notifying on the interval below instead of just once per AFK session. "
			+ "Also restarts the countdown infobox.",
		position = 9,
		section = repeatSection
	)
	default boolean repeatNotification()
	{
		return false;
	}

	@ConfigItem(
		keyName = "repeatInterval",
		name = "Repeat interval",
		description = "How often to repeat the notification after you've been marked AFK, once \"Repeat while "
			+ "AFK\" above is enabled.",
		position = 10,
		section = repeatSection
	)
	@Range(min = 1, max = 3600)
	@Units(Units.SECONDS)
	default int repeatInterval()
	{
		return 60;
	}

	@ConfigItem(
		keyName = "notification",
		name = "Notification",
		description = "How to notify you once the AFK threshold is reached.",
		position = 11
	)
	default Notification notification()
	{
		return Notification.ON;
	}
}

package com.ella.simpleafktimer;

import com.google.inject.Provides;
import java.awt.event.KeyEvent;
import java.time.Duration;
import java.time.temporal.ChronoUnit;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Constants;
import net.runelite.api.events.ClientTick;
import net.runelite.api.gameval.SpriteID;
import net.runelite.client.Notifier;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.KeyManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.infobox.InfoBoxManager;

@Slf4j
@PluginDescriptor(name = "Simple AFK Timer", description = "Notifies you once you've gone idle (no keyboard or "
		+ "mouse input) for a configurable amount of time", tags = { "afk", "idle", "timer", "notification",
				"alert" })
public class SimpleAfkTimerPlugin extends Plugin implements KeyListener
{
	@Inject
	private Client client;

	@Inject
	private Notifier notifier;

	@Inject
	private InfoBoxManager infoBoxManager;

	@Inject
	private KeyManager keyManager;

	@Inject
	private SpriteManager spriteManager;

	@Inject
	private SimpleAfkTimerConfig config;

	private boolean notifiedThisSession = false;
	private AfkCountdownInfoBox countdown;

	/**
	 * Set from {@link #keyPressed(KeyEvent)} on whatever thread the AWT key listener fires on and
	 * consumed from {@link #onClientTick(ClientTick)} on the client thread - volatile so the read
	 * side sees the write. Only ever written true off-thread and read+cleared on the client thread,
	 * so no further synchronization is needed.
	 */
	private volatile boolean arrowKeyPressed;

	/**
	 * Client ticks since the last arrow key press, advanced in lockstep with {@link
	 * Client#getKeyboardIdleTicks()} (exactly one per client tick, reset to zero on activity) so
	 * blending it in via {@link #computeIdleTicks()} preserves the exact-multiple-of-threshold check
	 * in {@link #onClientTick(ClientTick)}. Starts at {@link Integer#MAX_VALUE} so it never
	 * restricts anything until the first arrow key press of the session.
	 */
	private int arrowKeyIdleTicks = Integer.MAX_VALUE;

	@Provides
	SimpleAfkTimerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SimpleAfkTimerConfig.class);
	}

	@Override
	protected void startUp()
	{
		keyManager.registerKeyListener(this);
	}

	@Override
	protected void shutDown()
	{
		keyManager.unregisterKeyListener(this);
		removeCountdown();
		notifiedThisSession = false;
		arrowKeyPressed = false;
		arrowKeyIdleTicks = Integer.MAX_VALUE;
	}

	/**
	 * {@link Client#getKeyboardIdleTicks()} and {@link Client#getMouseIdleTicks()} count in client
	 * ticks ({@link Constants#CLIENT_TICK_LENGTH}, ~20ms, tied to the render loop) - NOT game ticks
	 * ({@link Constants#GAME_TICK_LENGTH}, 600ms) - confirmed against the core Idle Notifier
	 * plugin's own use of {@code Constants.CLIENT_TICK_LENGTH} to convert its thresholds. This must
	 * subscribe to {@link ClientTick} rather than {@link net.runelite.api.events.GameTick} so
	 * idleTicks is sampled once per increment - client tick rate is frame-rate dependent (fastest,
	 * and least regular, while the window is focused and actively rendering), so sampling less
	 * often than that made the exact-multiple check below miss its mark almost entirely whenever
	 * the window had focus.
	 */
	@Subscribe
	public void onClientTick(ClientTick event)
	{
		int idleTicks = computeIdleTicks();
		int thresholdTicks = Math.max(1, config.idleThreshold() * 1000 / Constants.CLIENT_TICK_LENGTH);

		if (idleTicks == 0)
		{
			removeCountdown();
			notifiedThisSession = false;
			return;
		}

		updateCountdown(idleTicks);

		if (idleTicks < thresholdTicks)
		{
			return;
		}

		// idleTicks and thresholdTicks both increase by exactly one per client tick once idle, so
		// their difference does too - it lands on every multiple of repeatIntervalTicks precisely,
		// starting from the moment the AFK threshold is first crossed, with no need to track elapsed
		// time separately.
		int repeatIntervalTicks = Math.max(1, config.repeatInterval() * 1000 / Constants.CLIENT_TICK_LENGTH);
		boolean atNotifyTick = (idleTicks - thresholdTicks) % repeatIntervalTicks == 0;
		if (!atNotifyTick)
		{
			return;
		}

		if (notifiedThisSession && !config.repeatNotification())
		{
			return;
		}

		int idleSeconds = idleTicks * Constants.CLIENT_TICK_LENGTH / 1000;
		notifier.notify(config.notification(), "You have been AFK for " + formatDuration(idleSeconds) + ".");
		notifiedThisSession = true;

		if (config.repeatNotification() && countdown != null)
		{
			countdown.updateDuration(Duration.ofSeconds(config.repeatInterval()));
		}
	}

	/**
	 * Combines whichever idle signals are enabled in config into a single client-tick idle count,
	 * blending in {@link #arrowKeyIdleTicks} when {@link SimpleAfkTimerConfig#detectArrowKeys()} is
	 * on. Returns 0 (never idle) if neither keyboard nor mouse detection is enabled.
	 */
	private int computeIdleTicks()
	{
		advanceArrowKeyIdleTicks();

		Integer combined = null;

		if (config.detectKeyboard())
		{
			int keyboardIdleTicks = client.getKeyboardIdleTicks();
			if (config.detectArrowKeys())
			{
				keyboardIdleTicks = Math.min(keyboardIdleTicks, arrowKeyIdleTicks);
			}
			combined = keyboardIdleTicks;
		}

		if (config.detectMouse())
		{
			int mouseIdleTicks = client.getMouseIdleTicks();
			combined = combined == null ? mouseIdleTicks : Math.min(combined, mouseIdleTicks);
		}

		return combined == null ? 0 : combined;
	}

	private void advanceArrowKeyIdleTicks()
	{
		if (arrowKeyPressed)
		{
			arrowKeyPressed = false;
			arrowKeyIdleTicks = 0;
		}
		else if (arrowKeyIdleTicks < Integer.MAX_VALUE)
		{
			arrowKeyIdleTicks++;
		}
	}

	@Override
	public void keyTyped(KeyEvent e)
	{
	}

	@Override
	public void keyPressed(KeyEvent e)
	{
		switch (e.getKeyCode())
		{
			case KeyEvent.VK_UP:
			case KeyEvent.VK_DOWN:
			case KeyEvent.VK_LEFT:
			case KeyEvent.VK_RIGHT:
				arrowKeyPressed = true;
				break;
		}
	}

	@Override
	public void keyReleased(KeyEvent e)
	{
	}

	/**
	 * Adds the countdown infobox once {@link SimpleAfkTimerConfig#infoboxDelay()} worth of idle time
	 * has passed and leaves it running from there - its own wall-clock countdown (not tied to game
	 * ticks) is what drives its displayed text, so nothing here needs to touch it once created except
	 * on a config change or {@link #removeCountdown()}. Since it's created partway through the idle
	 * session when the delay is non-zero, its period is the threshold *remaining* at that point, not
	 * the full threshold. Unlike a plain {@link net.runelite.client.ui.overlay.infobox.Timer}, {@link
	 * AfkCountdownInfoBox} doesn't remove itself once it reaches zero - it switches to showing
	 * "AFK" in red and stays up until {@link #removeCountdown()} takes it down.
	 */
	private void updateCountdown(int idleTicks)
	{
		if (!config.showInfobox())
		{
			removeCountdown();
			return;
		}

		int idleSeconds = idleTicks * Constants.CLIENT_TICK_LENGTH / 1000;
		if (idleSeconds < config.infoboxDelay())
		{
			return;
		}

		if (countdown == null)
		{
			int secondsRemaining = Math.max(0, config.idleThreshold() - idleSeconds);
			countdown = new AfkCountdownInfoBox(secondsRemaining, ChronoUnit.SECONDS, null, this);
			countdown.setTooltip("Time until AFK notification");
			infoBoxManager.addInfoBox(countdown);
			spriteManager.getSpriteAsync(SpriteID.LunarMagicOn.DREAM, 0, countdown);
		}
	}

	private void removeCountdown()
	{
		if (countdown != null)
		{
			infoBoxManager.removeInfoBox(countdown);
			countdown = null;
		}
	}

	private static String formatDuration(int totalSeconds)
	{
		int minutes = totalSeconds / 60;
		int seconds = totalSeconds % 60;

		if (minutes == 0)
		{
			return seconds + "s";
		}

		if (seconds == 0)
		{
			return minutes + "m";
		}

		return minutes + "m " + seconds + "s";
	}
}

package com.ella.simpleafktimer;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class SimpleAfkTimerPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(SimpleAfkTimerPlugin.class);
		RuneLite.main(args);
	}
}
